<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,Programme,Employer,ApprenticeSetupCase as C};
use App\Support\{CohortSetup as S};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Notification};
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class CohortSetupTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {$m=User::factory()->create(['role'=>'admin']);$n=User::factory()->create(['role'=>'ceo']);$t=User::factory()->create(['role'=>'tutor']);$p=Programme::factory()->create();$a=Apprentice::factory()->create(['tutor_id'=>$t->id,'programme_id'=>$p->id,'employer_id'=>null,'start_date'=>null,'planned_end_date'=>null,'email'=>'PRIVATE-LEARNER@example.test']);return compact('m','n','t','p','a');}
 private function data(array $f,string $issue='dates'):array {return ['issue'=>$issue,'owner_id'=>$f['n']->id,'due_on'=>today()->addDays(5)->toDateString(),'note'=>'PRIVATE-SETUP-ACTION'];}
 private function create(array $f,string $issue='dates'):C {return S::save($f['m'],1,$f['a'],null,0,S::check($f['a']->fresh())['hash'],$this->data($f,$issue));}
 private function invalid(callable $f):void {try{$f();$this->fail('Invalid case accepted');}catch(ValidationException){$this->assertTrue(true);}}
 public function test_all_profile_flags_are_operational_and_do_not_infer_active_or_eligibility():void {$f=$this->fixture();$check=S::check($f['a']);foreach(['account','staffing','dates','employer','tasks']as$code){$this->assertArrayHasKey($code,$check['issues']);}$this->assertArrayNotHasKey('identity',$check['issues']);$this->assertStringContainsString('not induction',$check['meaning']);$this->assertDatabaseCount('programme_outcomes',0);}
 public function test_duplicate_identity_email_and_bad_reference_are_visible_without_merging():void {$f=$this->fixture();Apprentice::factory()->create(['email'=>strtolower($f['a']->email)]);$this->assertArrayHasKey('identity',S::check($f['a'])['issues']);$f['a']->reference='bad lower';$f['a']->save();$this->assertArrayHasKey('identity',S::check($f['a'])['issues']);$this->assertDatabaseCount('apprentices',2);}
 public function test_readiness_filters_programme_group_dates_issue_and_literal_search():void {$f=$this->fixture();$other=Apprentice::factory()->create(['first_name'=>'PRIVATE-OTHER','programme_id'=>Programme::factory()->create()->id,'start_date'=>'2027-01-11']);$r=S::selected(['programme_id'=>$f['p']->id,'issue'=>'dates']);$this->assertCount(1,$r['rows']);$this->assertSame(1,$r['matched_profiles']);$this->assertSame(1,$r['counts']['dates']);$this->assertCount(0,S::selected(['search'=>'%'])['rows']);$this->assertCount(1,S::selected(['start_from'=>'2027-01-01','start_to'=>'2027-02-01'])['rows']);}
 public function test_cases_bind_current_source_owner_date_and_encrypt_action():void {$f=$this->fixture();$before=$f['a']->fresh()->getAttributes();$c=$this->create($f);$this->assertTrue(S::intact($c));$this->assertSame('Open',S::position($c,$f['a'])['label']);$raw=DB::table('apprentice_setup_cases')->value('details');$this->assertStringNotContainsString('PRIVATE-SETUP',$raw);$this->assertStringContainsString('PRIVATE-SETUP',Crypt::decryptString($raw));$this->assertSame($before,$f['a']->fresh()->getAttributes());}
 public function test_no_automatic_flag_or_duplicate_category_cannot_create_new_case():void {$f=$this->fixture();$this->invalid(fn()=>S::save($f['m'],1,$f['a'],null,0,S::check($f['a'])['hash'],$this->data($f,'identity')));$this->create($f);$this->invalid(fn()=>$this->create($f));$this->assertDatabaseCount('apprentice_setup_cases',1);}
 public function test_missing_or_wrong_owner_role_is_rejected_without_case():void {$f=$this->fixture();$d=$this->data($f);$d['owner_id']=$f['t']->id;$this->invalid(fn()=>S::save($f['m'],1,$f['a'],null,0,S::check($f['a'])['hash'],$d));$f['n']->active=false;$f['n']->save();$this->invalid(fn()=>$this->create($f));$this->assertDatabaseCount('apprentice_setup_cases',0);}
 public function test_stale_source_and_case_versions_refuse_metadata_changes():void {$f=$this->fixture();$c=$this->create($f);$hash=S::check($f['a'])['hash'];$f['a']->version++;$f['a']->save();$this->invalid(fn()=>S::save($f['m'],1,$f['a'],$c,1,$hash,$this->data($f)));$this->invalid(fn()=>S::save($f['m'],1,$f['a'],$c,2,S::check($f['a'])['hash'],$this->data($f)));$this->assertSame(1,$c->fresh()->version);}
 public function test_present_flag_cannot_be_manually_resolved():void {$f=$this->fixture();$c=$this->create($f);$this->invalid(fn()=>S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'resolve','Cannot override actual flag'));$this->assertSame('Open',$c->fresh()->state);}
 public function test_fixed_actual_source_can_resolve_and_later_drift_requires_recheck():void {$f=$this->fixture();$c=$this->create($f);$f['a']->start_date=today();$f['a']->planned_end_date=today()->addYears(3);$f['a']->version++;$f['a']->save();S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'resolve','PRIVATE-ACTUAL-SOURCE-CHECK');$c->refresh();$this->assertTrue(S::position($c,$f['a'])['resolved']);$f['a']->planned_end_date=null;$f['a']->version++;$f['a']->save();$position=S::position($c,$f['a']);$this->assertFalse($position['resolved']);$this->assertTrue($position['flag_present']);$this->assertStringContainsString('needs recheck',$position['label']);}
 public function test_deferral_is_source_bound_and_never_clears_automatic_flag():void {$f=$this->fixture();$c=$this->create($f);S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'defer','Needs actual source');$c->refresh();$p=S::position($c,$f['a']);$this->assertTrue($p['deferred']);$this->assertTrue($p['flag_present']);$this->assertFalse($p['resolved']);$this->assertArrayHasKey('dates',S::check($f['a'])['issues']);}
 public function test_overdue_deferral_refuses_and_due_metadata_can_be_rechecked():void {$f=$this->fixture();$c=$this->create($f);$this->travel(6)->days();$this->assertTrue(S::position($c,$f['a'])['overdue']);$this->invalid(fn()=>S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'defer','Past date'));$d=$this->data($f);$c=S::save($f['m'],1,$f['a'],$c,1,S::check($f['a'])['hash'],$d);$this->assertFalse(S::position($c,$f['a'])['overdue']);}
 public function test_withdrawal_does_not_hide_flags_and_reopening_retains_history():void {$f=$this->fixture();$c=$this->create($f);S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'withdraw','Not current tracking scope');$this->assertTrue(S::position($c->fresh(),$f['a'])['withdrawn']);$this->assertArrayHasKey('dates',S::check($f['a'])['issues']);S::decide($f['m'],1,$c->fresh(),2,S::check($f['a'])['hash'],'reopen','Track again');$this->assertSame('Open',$c->fresh()->state);$this->assertDatabaseCount('apprentice_setup_case_events',3);}
 public function test_changed_reference_needs_identity_rebaseline_or_withdraw_not_false_resolution():void {$f=$this->fixture();$c=$this->create($f);$f['a']->reference='CORRECTED-REFERENCE';$f['a']->start_date=today();$f['a']->planned_end_date=today()->addYear();$f['a']->save();$this->invalid(fn()=>S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'resolve','Identity changed'));$c=S::save($f['m'],1,$f['a'],$c,1,S::check($f['a'])['hash'],$this->data($f));$this->assertSame('CORRECTED-REFERENCE',$c->details['reference']);S::decide($f['m'],1,$c,2,S::check($f['a'])['hash'],'resolve','Rechecked identity and corrected dates');$this->assertTrue(S::position($c->fresh(),$f['a'])['resolved']);}
 public function test_plain_state_owner_date_or_proof_corruption_never_looks_verified():void {$f=$this->fixture();$c=$this->create($f);DB::table('apprentice_setup_cases')->where('id',$c->id)->update(['state'=>'Resolved']);$this->assertFalse(S::position($c->fresh(),$f['a'])['resolved']);DB::table('apprentice_setup_cases')->where('id',$c->id)->update(['owner_id'=>$f['m']->id]);$this->assertFalse(S::intact($c->fresh()));$this->actingAs($f['m'])->get('/apprentice-setup-actions/'.$c->id)->assertStatus(409);}
 public function test_required_save_audit_failure_rolls_back_case():void {$f=$this->fixture();AuditFault::install('setup_case_fault','apprentice_setup_case_events','Synthetic fail');try{$this->create($f);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('apprentice_setup_cases',0);}
 public function test_required_decision_audit_failure_rolls_back_proof():void {$f=$this->fixture();$c=$this->create($f);AuditFault::install('setup_decision_fault','apprentice_setup_case_events','Synthetic fail','case_defer');try{S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'defer','Synthetic');$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertSame('Open',$c->fresh()->state);$this->assertNull($c->fresh()->proof);}
 public function test_wrong_actor_role_and_stale_auth_are_rechecked():void {$f=$this->fixture();try{S::save($f['t'],1,$f['a'],null,0,S::check($f['a'])['hash'],$this->data($f));$this->fail('Wrong actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}$f['m']->auth_version=2;$f['m']->save();try{$this->create($f);$this->fail('Stale actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}}
 public function test_manager_routes_render_current_filters_forms_and_private_report():void {$f=$this->fixture();$c=$this->create($f);$this->actingAs($f['m'])->get('/apprentice-intakes/readiness?programme_id='.$f['p']->id.'&issue=dates')->assertOk()->assertSee($f['a']->reference)->assertHeader('Referrer-Policy','no-referrer')->assertDontSee('PRIVATE-LEARNER');$this->get('/apprentice-setup-actions/'.$c->id)->assertOk()->assertSee('PRIVATE-SETUP-ACTION');$this->get('/apprentice-intakes/actions?owner='.$f['n']->id.'&state=Open')->assertOk()->assertSee($f['a']->reference);$this->get('/apprentice-intakes/readiness.json')->assertOk()->assertDontSee('PRIVATE-')->assertJsonPath('private_names_emails_notes_exported',false);}
 public function test_non_managers_cannot_read_or_change_followup_or_cohort():void {$f=$this->fixture();$c=$this->create($f);foreach(['tutor','mentor','apprentice','employer','staff','careers_adviser','inclusion_lead']as$role){$u=User::factory()->create(['role'=>$role]);$this->actingAs($u);foreach(['/apprentice-intakes/readiness','/apprentice-intakes/readiness.json','/apprentice-intakes/actions','/apprentice-setup-actions/'.$c->id]as$url){$this->get($url)->assertForbidden();}$this->post('/apprentices/'.$f['a']->id.'/setup-actions',[])->assertForbidden();$this->post('/apprentice-setup-actions/'.$c->id,[])->assertForbidden();$this->post('/apprentice-setup-actions/'.$c->id.'/decision',[])->assertForbidden();}}
 public function test_case_create_and_decision_validation_requires_current_source_confirmation_and_real_owner():void {$f=$this->fixture();$d=[...$this->data($f),'version'=>0,'source_hash'=>S::check($f['a'])['hash'],'confirmed'=>1];$this->actingAs($f['m']);foreach(['source_hash','owner_id','due_on','confirmed']as$key){$v=$d;unset($v[$key]);$this->post('/apprentices/'.$f['a']->id.'/setup-actions',$v)->assertSessionHasErrors($key);}$this->post('/apprentices/'.$f['a']->id.'/setup-actions',$d)->assertRedirect()->assertSessionHasNoErrors();$this->assertDatabaseCount('apprentice_setup_cases',1);}
 public function test_read_only_gets_do_not_write_and_followup_sends_nothing():void {$f=$this->fixture();Notification::fake();$this->actingAs($f['m'])->get('/apprentice-intakes/readiness')->assertOk();$this->get('/apprentice-intakes/actions')->assertOk();$this->assertDatabaseCount('apprentice_setup_cases',0);$this->assertDatabaseCount('apprentice_setup_case_events',0);Notification::assertNothingSent();}
 public function test_stale_decision_form_and_missing_flag_deferral_refuse():void {$f=$this->fixture();$c=$this->create($f);$hash=S::check($f['a'])['hash'];$f['a']->start_date=today();$f['a']->planned_end_date=today()->addYear();$f['a']->save();$this->invalid(fn()=>S::decide($f['m'],1,$c,1,$hash,'resolve','Stale'));$this->invalid(fn()=>S::decide($f['m'],1,$c,1,S::check($f['a'])['hash'],'defer','Flag already clear'));$this->assertSame('Open',$c->fresh()->state);}
}
